INSERT INTO problems (id, slug, sector, places_json, sources_json) VALUES ('courier-settlement', 'courier-settlement', 'commerce', '["anywhere"]', '[{"title":"Pathao · Merchant terms, sections 3.21–3.31","url":"https://pathao.com/terms-of-service-merchant/","date":"Accessed 16 September 2026","en":"The terms describe COD collection, fee adjustments, payment statements and returns. They establish the workflow, not demand for a separate reconciliation tool.","bn":"শর্তে COD-এর টাকা সংগ্রহ, ফি সমন্বয়, পেমেন্টের স্টেটমেন্ট ও রিটার্নের প্রক্রিয়া আছে। আলাদা হিসাব মেলানোর টুলের চাহিদা আছে কি না, এই সোর্স থেকে তা জানা যায় না।"}]');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('courier-settlement', 'en', 'Couriers deliver. The accounts still don’t add up.', 'Growing online brands need to understand what was delivered, returned and paid across couriers.', 'The owner or operations lead of an online brand using more than one courier.', 'Orders, delivery status and money received sit in different records. Investigate whether reconciling them takes enough time, or leaves enough uncertainty, to justify another tool.', 'Will merchants pay for this separately when courier panels and accounting tools already cover part of the job?');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('courier-settlement', 'bn', 'ডেলিভারি হয়, কিন্তু পাওনার হিসাব মেলে না', 'একাধিক কুরিয়ারে কোন অর্ডার পৌঁছেছে, কোনটি ফেরত এসেছে আর কত টাকা পাওয়া গেছে, তা মিলিয়ে দেখতে হয় অনলাইন ব্র্যান্ডগুলোকে।', 'একাধিক কুরিয়ার ব্যবহার করে এমন অনলাইন ব্র্যান্ডের মালিক বা অপারেশন লিড।', 'অর্ডার, ডেলিভারির অবস্থা আর পাওয়া টাকার হিসাব আলাদা জায়গায় থাকে। এগুলো মেলাতে কত সময় যায়, কোথায় হিসাব আটকে যায়, আগে তা জেনে নিন।', 'কুরিয়ার প্যানেল ও অ্যাকাউন্টিং টুলে কাজের কিছু অংশ করা যায়। এর পরও আলাদা টুলের জন্য মার্চেন্ট টাকা দেবেন?');
INSERT INTO approaches (id, problem_id, kind, position) VALUES ('courier-settlement-approach', 'courier-settlement', 'software', 0);
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('courier-settlement-approach', 'en', 'Make courier payments add up', 'One place to match delivered orders, returns and courier payouts, so growing online brands can see what is still owed.', 'Start with permissioned CSV uploads. Match order IDs to settlements, flag exceptions and let the merchant correct the match. Keep an audit trail.', 'Test a monthly fee per merchant, with order volume as a possible pricing tier.', '["Ask three merchants to walk through their last settlement using redacted records.","Reconcile one week manually. Log missing IDs, fee differences and the time spent resolving them.","Show the exception list and offer a paid repeat of the service before building integrations."]', 'A merchant shares a second batch and agrees to pay for recurring reconciliation. Compliments on a demo are not enough.', 'A CSV import, an order-to-payment matching table and a review queue for unmatched items. Include duplicate IDs, partial payouts and returns in the synthetic sample data.');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('courier-settlement-approach', 'bn', 'কুরিয়ারের পাওনা মিলবে এক জায়গায়', 'কোন অর্ডার ডেলিভারি হলো, কোনটি ফেরত এলো আর কত টাকা পাওয়া গেল, সব মিলিয়ে অনলাইন ব্র্যান্ডের বাকি পাওনার হিসাব।', 'মার্চেন্টের অনুমতি নিয়ে CSV ফাইল দিয়ে শুরু করা যায়। অর্ডার আইডি ধরে টাকা মেলান, অমিলগুলো আলাদা দেখান। ভুল মিল হলে মার্চেন্ট তা ঠিক করবেন, আগের পরিবর্তনের রেকর্ডও থাকবে।', 'মার্চেন্টপ্রতি মাসিক ফি পরীক্ষা করা যায়। অর্ডারের সংখ্যা ধরে আলাদা প্যাকেজ লাগবে কি না, পরে দেখুন।', '["তিনজন মার্চেন্টের সঙ্গে বসে তাঁদের শেষ পেমেন্টের হিসাব দেখুন। ব্যক্তিগত তথ্য আগে সরিয়ে নিন।","এক সপ্তাহের হিসাব হাতে মিলিয়ে দেখুন। আইডি না মেলা, ফির পার্থক্য আর সমাধানে কত সময় গেল, লিখে রাখুন।","অমিলের তালিকা দেখিয়ে পরেরবার টাকার বিনিময়ে কাজটি করার প্রস্তাব দিন। তারপর ইন্টিগ্রেশন বানানোর কথা ভাবুন।"]', 'মার্চেন্ট আবার হিসাব মেলানোর কাজ দিলেন এবং নিয়মিত সেবার জন্য টাকা দিতে রাজি হলেন। ডেমো ভালো লেগেছে বললেই হবে না।', 'CSV আপলোড, অর্ডারের সঙ্গে পেমেন্ট মেলানোর টেবিল ও অমিল পর্যালোচনার তালিকা। নমুনা ডেটায় একই আইডি দুবার থাকা, আংশিক পেমেন্ট ও রিটার্ন রাখুন।');
INSERT INTO problems (id, slug, sector, places_json, sources_json) VALUES ('garment-offcuts', 'garment-offcuts', 'circular', '["gazipur","chattogram"]', '[{"title":"UNIDO · Circularity in Bangladesh’s textile value chain","url":"https://www.unido.org/news/bangladesh-circularity-opportunities-textile-value-chain","date":"28 February 2023","en":"A Bangladesh stakeholder roundtable discussed textile waste and circular production. This is sector context from 2023, not evidence of available stock or buyer willingness to pay.","bn":"বাংলাদেশে টেক্সটাইল বর্জ্য ও তা আবার উৎপাদনে কাজে লাগানো নিয়ে অংশীজনদের আলোচনা হয়েছিল। ২০২৩ সালের এই তথ্য খাতটি বুঝতে সাহায্য করে। এখন কত মাল পাওয়া যাবে বা ক্রেতা কত দাম দেবেন, তা এখান থেকে বোঝা যায় না।"}]');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('garment-offcuts', 'en', 'Usable garment offcuts are hard to match with buyers.', 'Factories and recyclers need to agree on material, quality and collection before a trade can work.', 'Factory waste managers and recyclers buying a specific fibre or quality of offcut.', 'Explore where existing trading relationships fail: inconsistent grading, unclear composition, irregular supply or collection costs. Do not assume a new marketplace is the missing piece.', 'Can reliable grading and repeat supply create more value than the cost of inspection, transport and existing intermediaries?');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('garment-offcuts', 'bn', 'ব্যবহারযোগ্য ঝুটের উপযুক্ত ক্রেতা খুঁজে পাওয়া কঠিন', 'ঝুটের ধরন, মান আর সংগ্রহের ব্যবস্থা নিয়ে কারখানা ও রিসাইক্লারের বোঝাপড়া হলেই কেনাবেচা এগোতে পারে।', 'কারখানায় ঝুটের দায়িত্বে থাকা ব্যক্তি এবং নির্দিষ্ট ফাইবার বা মানের ঝুট কেনেন এমন রিসাইক্লার।', 'চলতি কেনাবেচায় কোথায় সমস্যা হয়, আগে খুঁজে নিন। মান বোঝা, ফাইবারের তথ্য, নিয়মিত সরবরাহ বা পরিবহন খরচের কোনটি আসল বাধা? নতুন মার্কেটপ্লেসই দরকার, এমন ধরে নেবেন না।', 'মান যাচাই ও নিয়মিত সরবরাহের সুবিধা কি পরিদর্শন, পরিবহন ও মধ্যস্থতার খরচের চেয়ে বেশি হবে?');
INSERT INTO approaches (id, problem_id, kind, position) VALUES ('garment-offcuts-approach', 'garment-offcuts', 'marketplace', 0);
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('garment-offcuts-approach', 'en', 'Find the next use for garment offcuts', 'Help factories and recyclers trade fabric offcuts with clearer information about material, quality and collection.', 'Broker one narrowly defined material stream. Record fibre, colour, contamination, weight and pickup terms before adding a searchable stock list.', 'Test a disclosed fee for a completed transaction or a grading and collection service.', '["Speak to three factories and three buyers about one type of offcut.","With permission, document and grade a sample batch against a buyer’s actual specification.","Arrange one paid transaction and record the full inspection and collection cost."]', 'Both sides want to repeat the transaction at a price that covers the coordination work.', 'A material listing with composition, grade, sample photos, available weight and collection terms. Add a buyer request and a human-reviewed match; no invented stock.');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('garment-offcuts-approach', 'bn', 'গার্মেন্টসের ঝুট পাবে উপযুক্ত ক্রেতা', 'কাপড়ের ধরন, মান ও সংগ্রহের শর্ত পরিষ্কার থাকলে কারখানার ঝুট কিনতে রিসাইক্লারদের সুবিধা হবে কি না, তা পরীক্ষা করুন।', 'এক ধরনের ঝুটের লেনদেন দিয়ে শুরু করুন। ফাইবার, রং, মিশ্রণ, ওজন ও সংগ্রহের শর্ত লিখে রাখুন। এরপর খোঁজার মতো মালের তালিকা বানানো যায়।', 'সফল লেনদেনে আগে জানানো ফি অথবা মান যাচাই ও সংগ্রহের সেবার ফি পরীক্ষা করুন।', '["এক ধরনের ঝুট নিয়ে তিনটি কারখানা ও তিনজন ক্রেতার সঙ্গে কথা বলুন।","অনুমতি নিয়ে একটি নমুনা ব্যাচের তথ্য লিখুন। ক্রেতা যে মান চান, তার সঙ্গে মিলিয়ে দেখুন।","একটি টাকার লেনদেন করিয়ে পরিদর্শন ও সংগ্রহের পুরো খরচ হিসাব করুন।"]', 'দুই পক্ষই আবার লেনদেন করতে চায়, আর যে ফি দিতে রাজি তার মধ্যে সমন্বয়ের খরচ ওঠে।', 'ফাইবার, মান, নমুনার ছবি, ওজন ও সংগ্রহের শর্তসহ মালের তালিকা। ক্রেতার চাহিদা লিখে মানুষের পর্যালোচনায় মিল খোঁজার ব্যবস্থা রাখুন। কাল্পনিক মজুতকে আসল বলে দেখাবেন না।');
INSERT INTO problems (id, slug, sector, places_json, sources_json) VALUES ('shared-cold-delivery', 'shared-cold-delivery', 'agriculture', '["bogura","dhaka"]', '[{"title":"FAO · Sustainable food cold chains","url":"https://www.fao.org/energy/resources/videos/video-details/reducing-food-loss-and-waste-through-sustainable-food-cold-chains/en","date":"23 May 2023","en":"FAO explains the role of temperature-controlled storage and transport, including energy constraints. This is global background; it does not establish demand on a Bangladesh route.","bn":"নির্দিষ্ট তাপমাত্রায় খাবার রাখা ও পরিবহনের ভূমিকা এবং বিদ্যুতের সীমাবদ্ধতা ব্যাখ্যা করেছে FAO। এটি বিশ্বজুড়ে প্রযোজ্য পটভূমি। বাংলাদেশের কোনো নির্দিষ্ট রুটে চাহিদার প্রমাণ নয়।"}]');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('shared-cold-delivery', 'en', 'Small food shipments don’t fill a cold truck.', 'Suppliers with repeat buyers may need reliable cold transport at a scale they can afford.', 'A food supplier with repeat buyers but too little compatible volume for a dedicated vehicle.', 'Investigate whether small suppliers lose orders or margin because they cannot arrange reliable temperature-controlled transport. Start with one product and one route.', 'Will compatible shipments repeat at the same times, with enough margin after empty capacity, handling and spoilage risk?');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('shared-cold-delivery', 'bn', 'অল্প পণ্য পাঠাতে পুরো ঠান্ডা গাড়ি ভাড়া নিতে হয়', 'নিয়মিত ক্রেতা থাকলেও ছোট সরবরাহকারীর পক্ষে পুরো গাড়ির খরচ চালানো কঠিন হতে পারে। নির্ভরযোগ্য ছোট চালানের সুযোগ দরকার কি না, খুঁজে দেখুন।', 'নিয়মিত ক্রেতা আছে, কিন্তু নিজে একটি ঠান্ডা গাড়ি ভরার মতো উপযুক্ত মাল নেই, এমন খাবার সরবরাহকারী।', 'নির্ভরযোগ্য ঠান্ডা পরিবহন না পাওয়ায় ছোট সরবরাহকারীর অর্ডার বা লাভ কমছে কি না, খোঁজ নিন। একটি পণ্য ও একটি রুট ধরে শুরু করুন।', 'একসঙ্গে পাঠানো যায় এমন মাল কি একই সময়ে নিয়মিত আসবে? খালি জায়গা, ওঠানো-নামানো আর নষ্ট হওয়ার ঝুঁকি ধরেও লাভ থাকবে?');
INSERT INTO approaches (id, problem_id, kind, position) VALUES ('shared-cold-delivery-approach', 'shared-cold-delivery', 'service', 0);
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('shared-cold-delivery-approach', 'en', 'Book a little space in a cold delivery', 'Combine small food shipments on a repeat route instead of asking every supplier to fill a refrigerated vehicle.', 'Coordinate available capacity with an existing qualified operator. Keep product compatibility, temperature records, handling and delivery windows visible.', 'Test a per-shipment coordination fee with transparent transport and handling charges.', '["Interview suppliers and buyers on one proposed route. Map actual shipment days and product requirements.","Get an operator’s quote and handling plan; calculate the cost at partial capacity.","Only with suitable handling agreed, coordinate one paid trial and record temperatures, delays and the delivered condition."]', 'Repeat bookings cover the full trip cost and the buyer accepts the delivered product.', 'A booking board for one route showing product constraints, available capacity, delivery windows and a transparent quote. Use simulated records until an operator confirms a real trip.');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('shared-cold-delivery-approach', 'bn', 'ঠান্ডা গাড়িতে অল্প মাল পাঠানোর সুযোগ', 'প্রতিজন সরবরাহকারীকে পুরো গাড়ি ভরতে না দিয়ে একই রুটের উপযুক্ত ছোট চালানগুলো একসঙ্গে পাঠানো।', 'উপযুক্ত পরিবহন অপারেটরের খালি জায়গা কাজে লাগান। কোন পণ্য একসঙ্গে যাবে, তাপমাত্রা কত থাকবে, ওঠানো-নামানো ও পৌঁছানোর সময়, সব স্পষ্ট রাখুন।', 'পরিবহন ও ওঠানো-নামানোর খরচ আলাদা দেখিয়ে চালানপ্রতি সমন্বয়ের ফি পরীক্ষা করুন।', '["একটি সম্ভাব্য রুটের সরবরাহকারী ও ক্রেতাদের সঙ্গে কথা বলুন। কোন দিন মাল যায় আর পণ্যের কী শর্ত, লিখে নিন।","অপারেটরের কোটেশন ও মাল সামলানোর পরিকল্পনা নিন। গাড়ি পুরো না ভরলেও খরচ কত হবে, হিসাব করুন।","উপযুক্ত ব্যবস্থা নিশ্চিত করেই একটি টাকার পরীক্ষামূলক চালান পাঠান। তাপমাত্রা, দেরি ও পৌঁছানোর সময় পণ্যের অবস্থা লিখে রাখুন।"]', 'আবার বুকিং পাওয়া যায়, যাতায়াতের পুরো খরচ ওঠে এবং ক্রেতা পৌঁছানো পণ্য গ্রহণ করেন।', 'একটি রুটের বুকিং বোর্ডে পণ্যের শর্ত, খালি জায়গা, পৌঁছানোর সময় ও খরচ দেখান। অপারেটর চালান নিশ্চিত করার আগে কেবল নমুনা রেকর্ড ব্যবহার করুন।');
INSERT INTO problems (id, slug, sector, places_json, sources_json) VALUES ('bangla-order-notes', 'bangla-order-notes', 'commerce', '["anywhere"]', '[]');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('bangla-order-notes', 'en', 'Voice-note orders are easy to get wrong.', 'Order teams may lose time replaying messages and checking quantities, variants and addresses.', 'An order-taking team that already receives customer voice notes in Bangla.', 'Find out whether repeatedly listening to voice notes creates costly mistakes or delays. The need is a field hypothesis; no customer interviews have been completed for this brief.', 'Do accents, background noise and mixed product names leave more correction work than simply typing the order?');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('bangla-order-notes', 'bn', 'ভয়েস নোটের অর্ডারে ভুল থেকে যেতে পারে', 'পণ্যের পরিমাণ, ধরন আর ঠিকানা মিলিয়ে নিতে বারবার ভয়েস নোট শুনতে হয়। এতে কত সময় যায় আর কোথায় ভুল হয়, তা খুঁজে দেখুন।', 'ক্রেতার বাংলা ভয়েস নোট থেকে আগে থেকেই অর্ডার নেয় এমন টিম।', 'ভয়েস নোট বারবার শুনতে গিয়ে ভুল বা দেরি হচ্ছে কি না, খুঁজে দেখুন। এটি মাঠে যাচাই করার ধারণা। এই ব্রিফের জন্য এখনো ক্রেতার সাক্ষাৎকার নেওয়া হয়নি।', 'আঞ্চলিক উচ্চারণ, আশপাশের শব্দ ও মিশ্র ভাষায় পণ্যের নামের কারণে খসড়া ঠিক করতে কি হাতে লেখার চেয়েও বেশি সময় লাগবে?');
INSERT INTO approaches (id, problem_id, kind, position) VALUES ('bangla-order-notes-approach', 'bangla-order-notes', 'software', 0);
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('bangla-order-notes-approach', 'en', 'Turn a Bangla voice note into an order', 'A human-confirmed order draft from a voice note, with missing quantities, variants and addresses made obvious.', 'Extract a draft, show uncertainty and require a person to confirm each order. Begin with one product catalogue and never place orders automatically.', 'Test a team subscription against measured time saved and correction effort.', '["Observe a willing team processing voice orders and time the existing workflow.","With consent, test a small anonymised set. Compare the draft with the confirmed order.","Ask the team to use the draft-and-confirm workflow for a second session and discuss a paid trial."]', 'The full workflow is faster without increasing order errors, and a team agrees to a paid trial.', 'An audio upload, an editable order draft and highlighted uncertain fields. Use synthetic audio, require confirmation, and provide a clear delete action.');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('bangla-order-notes-approach', 'bn', 'বাংলা ভয়েস নোট থেকে অর্ডারের খসড়া', 'ভয়েস নোট শুনে অর্ডারের খসড়া হবে। পরিমাণ, ধরন বা ঠিকানা অস্পষ্ট থাকলে তা দেখাবে, মানুষ মিলিয়ে কনফার্ম করবেন।', 'খসড়ায় অনিশ্চিত অংশ আলাদা দেখান। প্রতিটি অর্ডার মানুষ মিলিয়ে কনফার্ম করবেন। একটি পণ্যের ক্যাটালগ দিয়ে শুরু করুন, নিজে থেকে অর্ডার পাঠানোর ব্যবস্থা রাখবেন না।', 'কত সময় বাঁচল ও ভুল ঠিক করতে কত কাজ হলো, তার সঙ্গে মিলিয়ে টিমের মাসিক ফি পরীক্ষা করুন।', '["রাজি আছে এমন একটি টিম কীভাবে ভয়েস অর্ডার নেয়, দেখুন। এখন কত সময় লাগে, মেপে নিন।","সম্মতি নিয়ে ব্যক্তিগত তথ্য সরানো কিছু রেকর্ডে পরীক্ষা করুন। কনফার্ম করা অর্ডারের সঙ্গে খসড়া মেলান।","টিমকে আরেকবার খসড়া মিলিয়ে কনফার্ম করার পদ্ধতি ব্যবহার করতে দিন। টাকার বিনিময়ে পরীক্ষার প্রস্তাব দিন।"]', 'অর্ডারে ভুল না বাড়িয়ে পুরো কাজে সময় কম লাগে, আর একটি টিম টাকা দিয়ে পরীক্ষা করতে রাজি হয়।', 'অডিও আপলোড, বদলানো যায় এমন অর্ডারের খসড়া ও অনিশ্চিত ঘর আলাদা দেখানোর ব্যবস্থা। বানানো নমুনা অডিও ব্যবহার করুন। কনফার্ম করা বাধ্যতামূলক রাখুন, মুছে দেওয়ার বোতামও দিন।');
INSERT INTO problems (id, slug, sector, places_json, sources_json) VALUES ('produce-crates', 'produce-crates', 'agriculture', '["bogura","dhaka"]', '[]');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('produce-crates', 'en', 'Produce packaging is used once, then lost.', 'Repeat produce routes may have a case for packaging that protects goods and reliably comes back.', 'A produce wholesaler and their regular suppliers on a short, repeat route.', 'Test whether handling damage or one-way packaging costs justify reusable crates. This brief proposes a research question, not a measured loss estimate.', 'Can crates return reliably and cheaply enough to make rental worthwhile?');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('produce-crates', 'bn', 'ফসলের প্যাকেট একবার ব্যবহার করেই ফেলে দিতে হয়', 'নিয়মিত একই পথে ফসল পাঠালে বারবার ব্যবহারযোগ্য ক্রেট কাজে আসতে পারে। পণ্য ভালো রাখা আর খালি ক্রেট ফেরত আনা, দুটোই পরীক্ষা করতে হবে।', 'ছোট একটি নিয়মিত রুটের পাইকার ও তাঁর কৃষিপণ্য সরবরাহকারীরা।', 'মাল ওঠানো-নামানোয় ক্ষতি বা একবার ব্যবহার করা প্যাকেজিংয়ের খরচ কি ক্রেট ভাড়া নেওয়ার কারণ হতে পারে? এই ব্রিফে প্রশ্নটি পরীক্ষা করার প্রস্তাব আছে, ক্ষতির মাপা পরিমাণ নেই।', 'ক্রেট কি নিয়মিত এবং এত কম খরচে ফেরত আসবে যে ভাড়ার সেবা চালানো যায়?');
INSERT INTO approaches (id, problem_id, kind, position) VALUES ('produce-crates-approach', 'produce-crates', 'service', 0);
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('produce-crates-approach', 'en', 'Rent produce crates that come back', 'A reusable crate pool for a repeat produce route, with collection, cleaning and returns built into the service.', 'Start with a small crate pool on one route. Track each handoff and agree return, cleaning and damage responsibilities before the first trip.', 'Test a per-trip rental fee and an agreed deposit; include loss and cleaning in the cost.', '["Watch one full produce journey and record handling and current packaging costs.","Agree a small paid trial with both ends of the route, including return and cleaning terms.","Track several complete return cycles, including damage, missing crates and collection time."]', 'Both sides rebook and the rental covers cleaning, collection, loss and replacement.', 'A simple crate register with check-out, handoff and return records. Show overdue returns and the actual cost per completed cycle.');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('produce-crates-approach', 'bn', 'ফসলের ক্রেট ভাড়া যাবে, ফেরতও আসবে', 'নিয়মিত একটি রুটে বারবার ব্যবহার করা যায় এমন ক্রেট ভাড়া। সংগ্রহ, পরিষ্কার ও ফেরত আনা সেবার মধ্যেই থাকবে।', 'একটি রুটে অল্প কিছু ক্রেট দিয়ে শুরু করুন। কার হাতে কখন গেল, লিখে রাখুন। প্রথম চালানের আগেই ফেরত, পরিষ্কার ও ক্ষতির দায় ঠিক করে নিন।', 'প্রতিবারের ভাড়া ও সম্মত জামানত পরীক্ষা করুন। হারানো ক্রেট ও পরিষ্কারের খরচও হিসাবের মধ্যে রাখুন।', '["একটি চালানের পুরো পথ দেখুন। মাল সামলানো ও এখনকার প্যাকেজিংয়ের খরচ লিখুন।","রুটের দুই পক্ষের সঙ্গে ছোট একটি টাকার পরীক্ষা ঠিক করুন। ফেরত ও পরিষ্কারের শর্তও রাখুন।","কয়েকবার যাওয়া ও ফেরত আসার পুরো হিসাব নিন। ভাঙা, হারানো ক্রেট ও সংগ্রহের সময় বাদ দেবেন না।"]', 'দুই পক্ষই আবার বুকিং দেয়। ভাড়া থেকে পরিষ্কার, সংগ্রহ, হারানো ও নতুন ক্রেট কেনার খরচ ওঠে।', 'ক্রেট দেওয়া, হাতবদল ও ফেরতের সাধারণ রেজিস্টার। ফেরত দিতে দেরি হচ্ছে কোনগুলো, আর একবার যাওয়া-আসায় আসল খরচ কত, দেখান।');
INSERT INTO problems (id, slug, sector, places_json, sources_json) VALUES ('factory-maintenance', 'factory-maintenance', 'manufacturing', '["gazipur","chattogram"]', '[]');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('factory-maintenance', 'en', 'A breakdown starts a search for the right technician.', 'Small factories need to know who can repair a particular machine, when they can come and what is needed.', 'The production manager of a small factory using a specific, common machine family.', 'Investigate how managers handle breakdowns today and whether finding a suitable technician is the bottleneck. Parts availability or payment terms may matter more.', 'Can a new service provide more reliability than a manager’s existing technician relationships?');
INSERT INTO problem_text (problem_id, locale, title, summary, customer, context, unknown) VALUES ('factory-maintenance', 'bn', 'মেশিন নষ্ট হলে উপযুক্ত মিস্ত্রি খোঁজা শুরু হয়', 'নির্দিষ্ট মেশিনটি কে ঠিক করতে পারবেন, কখন আসবেন আর কী লাগবে, তা আগে থেকে জানা ছোট কারখানার জন্য কাজে লাগতে পারে।', 'একটি নির্দিষ্ট প্রচলিত ধরনের মেশিন ব্যবহার করে এমন ছোট কারখানার প্রোডাকশন ম্যানেজার।', 'মেশিন বন্ধ হলে ম্যানেজার এখন কী করেন, জেনে নিন। উপযুক্ত টেকনিশিয়ান পাওয়াই কি বাধা? যন্ত্রাংশ বা পেমেন্টের শর্তও বড় সমস্যা হতে পারে।', 'ম্যানেজারের চেনা টেকনিশিয়ানের চেয়ে নতুন সেবা কি বেশি নির্ভরযোগ্য হতে পারবে?');
INSERT INTO approaches (id, problem_id, kind, position) VALUES ('factory-maintenance-approach', 'factory-maintenance', 'service', 0);
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('factory-maintenance-approach', 'en', 'Make machine repairs easier to arrange', 'Help small factories find an appropriate technician, agree a visit and keep a useful maintenance record.', 'Coordinate vetted technicians for one machine type in one industrial cluster. Record the diagnosis, approved scope, parts and work completed.', 'Test a transparent coordination fee, then explore a recurring maintenance plan only if visits repeat.', '["Interview three factory managers about their most recent breakdown, not an imagined future one.","Confirm skills and availability with technicians for that machine type.","Arrange one paid visit with a written scope, then check the outcome with both sides."]', 'The manager chooses the service again and the fee covers coordination and follow-up.', 'A service request, technician availability, an approved work order and a maintenance log. Do not generate repair instructions or promise response times you cannot deliver.');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('factory-maintenance-approach', 'bn', 'কারখানার মেশিন সারানোর লোক পাওয়া সহজ হোক', 'ছোট কারখানার জন্য উপযুক্ত টেকনিশিয়ান খোঁজা, আসার সময় ঠিক করা ও মেরামতের কাজের রেকর্ড রাখা।', 'একটি শিল্প এলাকায় এক ধরনের মেশিনের যাচাই করা টেকনিশিয়ান দিয়ে শুরু করুন। সমস্যা, অনুমোদিত কাজ, যন্ত্রাংশ ও শেষ করা কাজের রেকর্ড রাখুন।', 'আগে জানানো সমন্বয়ের ফি পরীক্ষা করুন। কাজ নিয়মিত হলে তবেই রক্ষণাবেক্ষণের প্যাকেজ বিবেচনা করুন।', '["তিনজন ম্যানেজারের সঙ্গে সর্বশেষ মেশিন নষ্ট হওয়ার ঘটনা নিয়ে কথা বলুন। ভবিষ্যতে কী হতে পারে, তা নিয়ে নয়।","ওই মেশিনের টেকনিশিয়ানদের দক্ষতা ও সময় মিলিয়ে নিন।","কী কাজ হবে লিখে একটি টাকার ভিজিট ঠিক করুন। পরে দুই পক্ষের কাছেই ফল জেনে নিন।"]', 'ম্যানেজার আবার সেবাটি নেন এবং ফি থেকে সমন্বয় ও পরে খোঁজ নেওয়ার খরচ ওঠে।', 'সেবার অনুরোধ, টেকনিশিয়ানের সময়, অনুমোদিত কাজের বিবরণ ও মেরামতের রেকর্ড। নিজে থেকে মেরামতের নির্দেশনা বানাবেন না, রাখতে পারবেন না এমন সময়ের প্রতিশ্রুতিও দেবেন না।');
INSERT INTO approaches (id, problem_id, kind, position) VALUES ('courier-settlement-service', 'courier-settlement', 'service', 1);
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('courier-settlement-service', 'en', 'Start with a reconciliation service', 'Do the work manually for one brand before building a product.', 'Collect exports from the merchant and reconcile one settlement period in a shared spreadsheet. Agree in advance which mismatches the service will investigate.', 'Test a fixed fee for one reconciliation period. Count the labour required before offering a recurring service.', '["Ask one merchant to walk through a past settlement with you.","Reconcile a small, permissioned and anonymized sample by hand.","Discuss whether resolving those mismatches would justify a paid repeat."]', 'The merchant can point to a repeated problem and a useful resolution; the work can be delivered at a sustainable cost.', 'A sample reconciliation worksheet using synthetic orders, fees, returns and payouts.');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('courier-settlement-service', 'bn', 'আগে হাতে হিসাব মেলানোর সেবা দিন', 'সফটওয়্যার বানানোর আগে একটি ব্র্যান্ডের হিসাব হাতে মিলিয়ে দেখুন।', 'মার্চেন্টের রিপোর্ট নিয়ে একটি নির্দিষ্ট সময়ের পাওনা স্প্রেডশিটে মিলিয়ে দিন। কোন কোন অমিল খুঁজে দেবেন, তা আগেই ঠিক করে নিন।', 'একটি সময়ের হিসাব মেলাতে নির্দিষ্ট ফি চাইতে পারেন। নিয়মিত সেবা দেওয়ার আগে কতটা শ্রম লাগছে, তা হিসাব করুন।', '["একজন মার্চেন্টের সঙ্গে আগের একটি সময়ের হিসাব দেখে নিন।","অনুমতি নিয়ে পরিচয় মুছে ফেলা ছোট একটি নমুনা হাতে মিলিয়ে দেখুন।","অমিলগুলো মিটলে মার্চেন্ট আবার এই সেবা কিনবেন কি না, আলোচনা করুন।"]', 'মার্চেন্ট বারবার হওয়া সমস্যাটি দেখাতে পারছেন, সমাধান তাঁর কাজে লাগছে এবং সেবার খরচও সামলানো যাচ্ছে।', 'বানানো অর্ডার, ফি, রিটার্ন ও পাওনা দিয়ে হিসাব মেলানোর একটি নমুনা ওয়ার্কশিট।');
INSERT INTO approaches (id, problem_id, kind, position) VALUES ('bangla-order-confirmation', 'bangla-order-notes', 'workflow', 1);
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('bangla-order-confirmation', 'en', 'Confirm the order before processing it', 'Try a short confirmation step without automated transcription.', 'An order taker listens once, records the essentials in a standard form and sends a concise confirmation to the customer. Study whether this catches the consequential mistakes.', 'First test it as an internal workflow. A paid training or setup service is only a hypothesis if other teams want help adopting it.', '["Review a few anonymized mistaken orders with the team.","Use one confirmation format for a small set of new orders.","Compare missing details and staff effort with the previous workflow."]', 'The confirmation prevents meaningful mistakes without introducing more work than it saves.', 'A mobile order form and customer confirmation preview with clearly synthetic names and products.');
INSERT INTO approach_text (approach_id, locale, title, summary, description, business_model, steps_json, signal, prototype) VALUES ('bangla-order-confirmation', 'bn', 'অর্ডার নেওয়ার পর ক্রেতার সঙ্গে মিলিয়ে নিন', 'অডিও থেকে লেখা তৈরির সফটওয়্যার ছাড়াই ছোট একটি নিশ্চিতকরণ ধাপ পরীক্ষা করুন।', 'কর্মী একবার শুনে নির্দিষ্ট ফরমে অর্ডারের দরকারি তথ্য লিখবেন, তারপর ক্রেতাকে ছোট একটি বার্তা পাঠিয়ে মিলিয়ে নেবেন। বড় ভুলগুলো এতে ধরা পড়ে কি না, দেখুন।', 'আগে নিজেদের কাজের পদ্ধতি হিসেবে পরীক্ষা করুন। অন্য দলকে শেখানো বা চালু করে দেওয়ার সেবা বিক্রি করা যাবে কি না, তা পরে যাচাই করতে হবে।', '["দলের সঙ্গে ভুল হওয়া কয়েকটি অর্ডার পরিচয় মুছে দেখে নিন।","অল্প কিছু নতুন অর্ডারে একইভাবে তথ্য মিলিয়ে নিন।","আগের পদ্ধতির সঙ্গে বাদ পড়া তথ্য আর কর্মীদের সময় তুলনা করুন।"]', 'তথ্য মিলিয়ে নেওয়ার ধাপটি কাজে লাগার মতো ভুল ঠেকাচ্ছে, অথচ বাঁচানো সময়ের চেয়ে বেশি সময় নিচ্ছে না।', 'নমুনা নাম ও পণ্য দিয়ে মোবাইলে অর্ডার লেখার ফরম এবং ক্রেতাকে পাঠানোর বার্তার প্রিভিউ।');
