INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_bangladesh-angels-network', 'en', 'Bangladesh Angels Network', 'A member-led angel network that syndicates investments into early-stage, Bangladesh-linked digital businesses. BAN helps selected founders prepare their deck, data room and fundraising strategy before presenting them to angels for diligence and a common term sheet.');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_bangladesh-angels-network', 'bn', 'Bangladesh Angels Network', 'সদস্যদের পরিচালিত এই অ্যাঞ্জেল নেটওয়ার্কটি প্রাথমিক পর্যায়ের বাংলাদেশ-সম্পর্কিত ডিজিটাল ব্যবসায় যৌথভাবে বিনিয়োগ করে। BAN নির্বাচিত ফাউন্ডারদের পিচ ডেক, ডেটা রুম ও ফান্ড সংগ্রহের পরিকল্পনা গুছিয়ে নিতে সাহায্য করে। এরপর যৌথ ডিউ ডিলিজেন্স ও সমন্বিত টার্ম শিটের জন্য ইনভেস্টরদের সামনে উপস্থাপন করে।');
INSERT INTO connections (id, organization_id, problem_id, stage, work_en, work_bn, evidence_url, review_scope, reviewed_at) VALUES ('connection_pathao_settlements', 'org_pathao', 'courier-settlement', 'live', 'Pathao’s merchant terms describe COD collection and settlement. It is an existing courier service to study; this source does not establish that Pathao solves reconciliation across different couriers.', 'Pathao-এর মার্চেন্ট শর্তে COD-এর টাকা সংগ্রহ ও মার্চেন্টকে দেওয়ার প্রক্রিয়া আছে। চালু কুরিয়ার সেবা হিসেবে এটি দেখে নিতে পারেন। তবে বিভিন্ন কুরিয়ারের হিসাব একসঙ্গে মেলানোর সমাধান Pathao দেয়, এমন প্রমাণ এই সোর্সে নেই।', 'https://pathao.com/terms-of-service-merchant/', 'public-source-context', '2026-09-16T00:00:00Z');
